"""Models for reactive reassessment on incoming clinical updates."""

from pydantic import BaseModel, Field


class ImpactAssessment(BaseModel):
    """Output of the bounded impact-assessment call."""

    summary: str
    affects_discharge: bool
    discharge_impact: str
    # Whether the existing recommendations should be regenerated by re-running
    # the full Social Care Agent pipeline.
    recommend_rerun: bool
    recommendation_note: str


class ReassessmentRecord(BaseModel):
    """A stored impact assessment, kept on the referral's reassessment history."""

    reassessed_at: str
    update_ids: list[str] = Field(default_factory=list)
    summary: str
    affects_discharge: bool
    discharge_impact: str
    recommend_rerun: bool
    recommendation_note: str


class ReassessResponse(BaseModel):
    """Result of a reassessment trigger.

    ``changed`` is false when there were no new updates to act on, so the caller
    knows the expensive pipeline was deliberately not re-run.
    """

    changed: bool
    message: str = ""
    impact: ReassessmentRecord | None = None
